export const empty=()=>({x:0,y:0,action:false,alt:false,pressed:false,altPressed:false});
export function controlMarkup(i,label){return `<div class="touch-player" data-player="${i}"><span>${label}</span><div class="dpad"><button data-key="up" aria-label="${label}向上">↑</button><button data-key="left" aria-label="${label}向左">←</button><button data-key="right" aria-label="${label}向右">→</button><button data-key="down" aria-label="${label}向下">↓</button></div><div class="action-pad"><button data-key="action" aria-label="${label}主要动作">A</button><button data-key="alt" aria-label="${label}辅助动作">B</button></div></div>`}
export function bindTouch(root,onChange){const held=new Map();function update(){const states=[empty(),empty()];for(const {player,key}of held.values()){const s=states[player];if(key==='left')s.x--;if(key==='right')s.x++;if(key==='up')s.y--;if(key==='down')s.y++;if(key==='action')s.action=true;if(key==='alt')s.alt=true}onChange(states);root.querySelectorAll('[data-key]').forEach(b=>b.classList.toggle('held',[...held.values()].some(h=>h.player===+b.closest('[data-player]').dataset.player&&h.key===b.dataset.key)))}root.querySelectorAll('[data-key]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();try{b.setPointerCapture(e.pointerId)}catch{}held.set(e.pointerId,{player:+b.closest('[data-player]').dataset.player,key:b.dataset.key});update()});for(const type of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(type,e=>{held.delete(e.pointerId);update()})});const clear=()=>{held.clear();update()};addEventListener('blur',clear);document.addEventListener('visibilitychange',()=>{if(document.hidden)clear()});return{clear}}
